// @generated by:gauntlet run:godseye-local-database
import { randomBytes, randomUUID } from "node:crypto";
import {
  CONTROL_API_HEADER,
  CONTROL_API_VERSION,
  DatabaseOverview,
  DatabasePreparation,
  ProjectResponse,
} from "@godseye/contracts";
import { InfrastructureEngine } from "@godseye/core";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createApp } from "../apps/control-api/src/app.js";
import { loadConfiguration } from "../apps/control-api/src/config.js";
import { createControlClient } from "../packages/control-client/src/index.js";
import { projectInput } from "./helpers.js";
import { type OwnerAuthFixture, ownerAuthFixture } from "./owner-auth-fixture.js";
import { fixtureProfile } from "./pg-helpers.js";

describe("strict private owner database HTTP and client contract", () => {
  let fixture: OwnerAuthFixture;
  let infrastructure: InfrastructureEngine;
  let app: ReturnType<typeof createApp>;
  let headers: Headers;
  beforeEach(async () => {
    fixture = await ownerAuthFixture();
    infrastructure = new InfrastructureEngine(fixture.store);
    app = createApp(
      fixture.core,
      loadConfiguration({ GODSEYE_MODE: "local" }),
      fixture.identity,
      infrastructure.foundation,
      undefined,
      infrastructure,
    );
    headers = (await fixture.session()).headers;
    headers.set(CONTROL_API_HEADER, CONTROL_API_VERSION);
  });
  afterEach(async () => fixture.close());
  function request(path: string, method = "GET", body?: unknown, key = randomUUID()) {
    const selected = new Headers(headers);
    if (method !== "GET") selected.set("idempotency-key", key);
    return app.request(new URL(`/api/v1${path}`, fixture.origin), {
      method,
      headers: selected,
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    });
  }
  async function preparationInput() {
    const response = await request("/projects", "POST", projectInput);
    expect(response.status).toBe(201);
    const saved = ProjectResponse.parse(await response.json()),
      environment = saved.environments[0];
    if (!environment) throw new Error("Missing fixture environment");
    return {
      projectId: saved.id,
      environmentId: environment.id,
      expectedProjectRevision: saved.revision,
      expectedEnvironmentRevision: environment.revision,
      profile: fixtureProfile,
    };
  }
  function client(
    fetcher: typeof fetch = async (input, init) => app.request(new Request(input, init)),
  ) {
    return createControlClient({ baseUrl: `${fixture.origin}/api/v1`, headers, fetch: fetcher });
  }

  it("T-AC-33 authenticates owner database commands before validating their body", async () => {
    for (const [method, path] of [
      ["GET", "/databases"],
      ["POST", "/databases/preparations"],
      ["POST", "/databases/admissions"],
    ]) {
      const response = await app.request(new URL(`/api/v1${path}`, fixture.origin), {
        method,
        headers: fixture.headers(),
        ...(method === "GET" ? {} : { body: "{}" }),
      });
      expect(response.status).toBe(401);
    }
  });

  it("T-AC-33 derives unconfigured backup, restore and rotation states honestly", async () => {
    const response = await request("/databases");
    expect(response.status).toBe(200);
    expect(DatabaseOverview.parse(await response.json())).toMatchObject({
      execution: "unconfigured",
      backup: "unconfigured",
      restore: "unconfigured",
      rotation: "unconfigured",
      preparations: [],
      allocations: [],
    });
  });

  it("T-AC-33 requires recent passkey authority for preparation and admission", async () => {
    const input = await preparationInput();
    headers = (await fixture.session(6 * 60_000)).headers;
    for (const [path, body] of [
      ["/databases/preparations", input],
      [
        "/databases/admissions",
        { preparationId: randomUUID(), expectedHash: "a".repeat(64), intent: "provision" },
      ],
    ] as const) {
      const response = await request(path, "POST", body);
      expect(response.status).toBe(403);
      expect(await response.json()).toMatchObject({ error: { code: "STEP_UP_REQUIRED" } });
    }
  });

  it("T-AC-33 rejects a missing durable mutation key without recording a preparation", async () => {
    const response = await app.request(new URL("/api/v1/databases/preparations", fixture.origin), {
      method: "POST",
      headers,
      body: JSON.stringify(await preparationInput()),
    });
    expect(response.status).toBe(400);
    expect(DatabaseOverview.parse(await (await request("/databases")).json()).preparations).toEqual(
      [],
    );
  });

  it("T-AC-31 T-AC-33 rejects SQL, connection material and execution escape fields without echoing them", async () => {
    const input = await preparationInput(),
      marker = randomBytes(32).toString("base64url");
    for (const injected of [
      { sql: marker },
      { profile: { ...fixtureProfile, connectionString: marker } },
      { profile: { ...fixtureProfile, providerId: marker } },
      { actor: { kind: "owner", id: marker } },
    ]) {
      const response = await request("/databases/preparations", "POST", { ...input, ...injected });
      expect(response.status).toBe(422);
      expect(await response.text()).not.toContain(marker);
    }
    expect(DatabaseOverview.parse(await (await request("/databases")).json()).preparations).toEqual(
      [],
    );
  });

  it("T-AC-33 prepares replayable profiles but refuses admission when execution is unqualified", async () => {
    const input = await preparationInput(),
      key = randomUUID();
    const first = await request("/databases/preparations", "POST", input, key);
    expect(first.status).toBe(201);
    const preparation = DatabasePreparation.parse(await first.json());
    const replay = await request("/databases/preparations", "POST", input, key);
    expect(await replay.json()).toEqual(preparation);
    const refused = await request("/databases/admissions", "POST", {
      preparationId: preparation.id,
      expectedHash: preparation.hash,
      intent: "provision",
    });
    expect(refused.status).toBe(503);
    expect(DatabaseOverview.parse(await (await request("/databases")).json()).allocations).toEqual(
      [],
    );
  });

  it("T-AC-31 T-AC-33 bounds unexpected producer material without leaking authority", async () => {
    const marker = randomBytes(32).toString("base64url"),
      original = infrastructure.database.overview.bind(infrastructure.database);
    infrastructure.database.overview = async (actor) => ({
      ...(await original(actor)),
      connectionMaterial: marker,
    });
    const response = await request("/databases"),
      body = await response.text();
    expect(response.status).toBe(500);
    expect(body).not.toContain(marker);
    expect(body.length).toBeLessThan(1024);
    expect(JSON.parse(body)).toMatchObject({ error: { code: "INTERNAL_ERROR" } });
  });

  it("T-AC-33 uses the real typed client to prepare cells and preserve structured unavailability", async () => {
    const input = await preparationInput(),
      control = client(),
      key = randomUUID();
    const prepared = await control.prepareDatabase(input, key);
    expect(await control.prepareDatabase(input, key)).toEqual(prepared);
    expect(await control.databaseOverview()).toMatchObject({ execution: "unconfigured" });
    await expect(
      control.admitDatabase(
        { preparationId: prepared.id, expectedHash: prepared.hash, intent: "provision" },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ name: "ControlHttpError", status: 503 });
    await expect(control.prepareDatabase(input, "")).rejects.toThrow(/idempotency/i);
  });

  it("T-AC-33 publishes strict OpenAPI commands and exposes no owner SQL or destructive shortcut", async () => {
    const response = await request("/openapi.json"),
      document = await response.json();
    expect(response.status).toBe(200);
    for (const path of ["/api/v1/databases/preparations", "/api/v1/databases/admissions"]) {
      expect(document.paths[path].post.parameters).toEqual(
        expect.arrayContaining([
          expect.objectContaining({
            name: expect.stringMatching(/^idempotency-key$/i),
            required: true,
          }),
        ]),
      );
    }
    for (const path of [
      "/databases/sql",
      "/databases/providers",
      "/databases/delete",
      "/databases/export",
      "/databases/restore",
    ])
      expect((await request(path, "POST", {})).status).toBe(404);
  });
});
